import json, sys

BASE = "https://freya-bank-final.egemenayrac.workers.dev/voice/v1/"
HDR = {"type": "object", "properties": {
    "Content-Type": {"type": "string", "default": "application/json"},
    "Accept": {"type": "string", "default": "application/json"},
    "Authorization": {"type": "string", "default": "Bearer test"}}}

POST_HOOK = '''try:
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        sc = result.get('status_code')
        ok = isinstance(d, dict) and isinstance(d.get('result'), dict) and str(d['result'].get('returnCode')) == '1' and 'data' in d
        if ok:
            d['what_to_do_next'] = 'OK. Basarili.'
        else:
            result['data'] = {'ok': False, 'error': 'service_failed', 'what_to_do_next': 'Servis hatasi. Hicbir islem yapilmadi. Musteriye basarili oldugunu ASLA soyleme.'}
except Exception:
    pass
'''


def api_fn(name, path, body_props, required=None, desc="", timeout=15000):
    return {
        "type": "function",
        "config": {"timeoutMs": timeout, "maxRetries": 0},
        "function": {
            "name": name, "handler": "__function__:api_call", "description": desc or name,
            "parameters": {"type": "object", "properties": {
                "url": {"type": "string", "default": BASE + path},
                "method": {"type": "string", "default": "POST"},
                "headers": HDR,
                "body": {"type": "object", "properties": {
                    "data": {"type": "object", "properties": body_props, "required": required or list(body_props)},
                    "call": {"type": "object", "properties": {"ani": {"type": "string", "default": ""}, "lang": {"type": "string", "default": "tr"}}}
                }, "required": ["data"]}}}},
        "post_process_code": POST_HOOK,
    }


def api_node(name, fn, mapping, nxt):
    return {"name": name, "node_type": "api_request", "passthrough": True,
            "passthrough_default_transition": nxt, "on_enter": {"type": "silent"},
            "pre_actions": [fn], "response_mapping": mapping,
            "transitions": [{"target_node": nxt, "description": "always", "condition": {"operator": "always"}}]}


def code_node(name, code, transitions, default):
    code = code.replace("{{", "{ {").replace("}}", "} }")
    return {"name": name, "node_type": "code", "passthrough": True,
            "passthrough_default_transition": default, "on_enter": {"type": "silent"},
            "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec",
                             "parameters": {"type": "object", "properties": {
                                 "code": {"type": "string", "default": code},
                                 "timeout_ms": {"type": "number", "default": 15000}}}}}],
            "transitions": transitions + [{"target_node": default, "description": "always", "condition": {"operator": "always"}}]}


def eq(var, val, target, desc):
    return {"target_node": target, "description": desc,
            "condition": {"logic": "or", "conditions": [{"variable": var, "operator": "equals", "operand": val}]}}


def intent(target, desc):
    return {"target_node": target, "description": desc, "condition": {"operator": "matches_intent", "description": desc}}


def end_node(name, msg):
    return {"name": name, "node_type": "end_call", "on_enter": {"type": "silent"},
            "terminal": {"type": "function", "function": {"name": name, "handler": "__function__:end_call",
                         "parameters": {"type": "object", "properties": {
                             "message_mode": {"type": "string", "default": "custom"},
                             "spoken_message": {"type": "string", "default": msg}}}}},
            "transitions": []}


HELPERS = r'''
import json, re, datetime
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
AY = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
def w3(n):
    h, r = divmod(n, 100); t, o = divmod(r, 10)
    s = []
    if h: s.append(('' if h == 1 else ONES[h] + ' ') + 'yüz')
    if t: s.append(TENS[t])
    if o: s.append(ONES[o])
    return ' '.join(s)
def words(n):
    n = int(n)
    if n == 0: return 'sıfır'
    parts = []
    for val, nm in ((10**9, 'milyar'), (10**6, 'milyon'), (1000, 'bin')):
        q, n = divmod(n, val)
        if q:
            parts.append('bin' if (val == 1000 and q == 1) else w3(q) + ' ' + nm)
    if n: parts.append(w3(n))
    return ' '.join(parts)
def money(x, unit, sub):
    x = round(abs(float(x)) + 1e-9, 2)
    a = int(x); c = int(round((x - a) * 100))
    s = words(a) + ' ' + unit
    if c: s += ' ' + words(c) + ' ' + sub
    return s
def tl(x): return money(x, 'Türk Lirası', 'kuruş')
def pdate(s):
    try:
        d, m, y = str(s).strip().split('.')
        return datetime.date(int(y), int(m), int(d))
    except Exception:
        return None
def sdate(s):
    d = pdate(s)
    return ('%d %s %d' % (d.day, AY[d.month], d.year)) if d else str(s)
def digits(s): return ' '.join(DIG[int(c)] for c in str(s) if c.isdigit())
def today():
    try: return datetime.date.fromisoformat(str(vars.get('now') or '')[:10])
    except Exception: return datetime.date.today()
def load(name, prefix):
    v = vars.get(name)
    if isinstance(v, str):
        try: v = json.loads(v)
        except Exception: v = None
    if isinstance(v, (dict, list)) and v: return v
    flat = {}
    for k in list(vars.keys()):
        if k.startswith(prefix):
            flat[k[len(prefix):]] = vars.get(k)
    if not flat: return None
    root = {}
    for k, val in flat.items():
        cur = root; ps = k.split('.')
        for p in ps[:-1]: cur = cur.setdefault(p, {})
        cur[ps[-1]] = val
    def fix(o):
        if isinstance(o, dict):
            if o and all(str(k).isdigit() for k in o):
                return [fix(o[k]) for k in sorted(o, key=lambda z: int(z))]
            return {k: fix(v2) for k, v2 in o.items()}
        return o
    return fix(root)
def num(x):
    try: return float(x)
    except Exception: return 0.0
'''

PREP_CARDS = HELPERS + r'''
try:
    vars['card_state'] = 'error'
    vars['card_count'] = '0'
    vars['cards_table'] = ''
    vars['card_examples'] = ''
    vars['current_card'] = ''
    vars['get_balance_status'] = 'none'
    vars['reads_done'] = '0'
    vars['pdf_sends'] = '0'
    data = load('cards_data', 'cards_list_response.data.data.')
    sc = str(vars.get('cards_list_response.status_code') or vars.get('cards_list_status_code') or '')
    cards = None
    if isinstance(data, dict):
        cards = data.get('cards')
    if isinstance(cards, list) and cards:
        main = [c for c in cards if isinstance(c, dict) and str(c.get('isMainCard')).lower() == 'true']
        use = main if main else []
        if not use:
            vars['card_state'] = 'none'
        else:
            vars['card_count'] = str(len(use))
            lines = []
            for i, c in enumerate(use):
                nm = c.get('productName') or ''
                lines.append('- Kart %d: ad "%s", son dört hane %s (okunuşu: %s), cardNumber = %s' % (i + 1, nm or '(adı yok)', c.get('cardNumberLast4'), digits(c.get('cardNumberLast4')), c.get('cardNumber')))
            vars['cards_table'] = '\n'.join(lines)
            names = []
            for c in use:
                if c.get('productName') and c.get('productName') not in names: names.append(c.get('productName'))
            vars['card_examples'] = ' veya '.join(names[:2]) if names else ''
            if len(use) == 1:
                vars['current_card'] = use[0].get('cardNumber')
                vars['card_state'] = 'single'
            else:
                vars['card_state'] = 'multi'
    elif '404' in sc or 'FB_IVR_CHANNEL_102' in json.dumps(data or {}) or str(vars.get('cards_list_response.data.data.validCardsCount') or '') == '0':
        vars['card_state'] = 'none'
    if vars['card_state'] == 'error' and '404' in sc:
        vars['card_state'] = 'none'
except Exception as e:
    vars['card_state'] = 'error'
'''

PREP_EMAIL = HELPERS + r'''
try:
    vars['has_email'] = 'no'
    vars['email_addr'] = ''
    em = str(vars.get('email_data_email') or vars.get('contact_email_get_response.data.data.ibanEmail') or '').strip()
    ct = str(vars.get('contact_email_get_response.data.data.communicationType') or '')
    if em and '@' in em and ct != 'Phone':
        vars['has_email'] = 'yes'
        vars['email_addr'] = em
except Exception:
    vars['has_email'] = 'no'
'''

COMPOSE = HELPERS + r'''
try:
    vars['reading_state'] = 'error'
    b = load('bal', 'get_balance_response.data.data.')
    if isinstance(b, dict) and b.get('cardNumberLast4'):
        vars['reading_state'] = 'ok'
        t = today()
        last4 = digits(b.get('cardNumberLast4'))
        nm = b.get('productName') or ''
        intro = 'Sonu %s ile biten %s' % (last4, (nm + ' kartınız') if nm else 'kartınız')
        sd, lp = b.get('statementDate'), b.get('lastPayDate')
        sdd, lpd = pdate(sd), pdate(lp)
        out = []
        top = str(b.get('statementPaymentStatus') or '')
        cur = {'TL': ('Türk Lirası', 'Türk Lirası', 'kuruş'), 'USD': ('Dolar', 'dolar', 'sent'), 'EUR': ('Euro', 'euro', 'sent'), 'GBP': ('İngiliz Sterlini', 'İngiliz sterlini', 'peni')}
        blocks = {}
        for code in ('TL', 'USD', 'EUR', 'GBP'):
            blk = b.get('debt' + code)
            if isinstance(blk, dict) and blk: blocks[code] = blk
        vars['pdf_currency'] = 'TL'
        if sdd and sdd == t:
            out.append('Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
        if top == 'NO_DEBT' or not sdd:
            tot = num((blocks.get('TL') or {}).get('totalDebt'))
            s = '%sın %s tarihli ekstresinden borcunuz bulunmamaktadır.' % (intro, sdate(sd)) if sdd else '%s için kesilmiş bir ekstre borcunuz bulunmamaktadır.' % intro
            out.append(s)
            if sdd:
                out.append('Gelecek dönemler dahil toplam borcunuz %s\'dır.' % tl(max(tot, 0)))
                nlp = b.get('nextLastPayDate') or lp
                out.append('Son ödeme tarihiniz %s olacaktır.' % sdate(nlp))
        else:
            first = True
            def pre():
                return '%sa ait %s tarihinde kesilen ekstre ' % (intro, sdate(sd))
            clear = []
            debtors = []
            for code in ('TL', 'USD', 'EUR', 'GBP'):
                if code not in blocks: continue
                blk = blocks[code]
                rd = num(blk.get('remainingDebt')); sdbt = num(blk.get('statementDebt'))
                if code == 'TL':
                    has = rd > 0.0001
                else:
                    has = str(blk.get('statementPaymentStatus')) == 'HAS_DEBT' and (sdbt > 0.0001 or rd > 0.0001)
                if not has:
                    clear.append(cur[code][0]); continue
                debtors.append(code)
            if debtors: vars['pdf_currency'] = debtors[0]
            for code in debtors:
                blk = blocks[code]
                nmc, unit, sub = cur[code]
                f = lambda x: money(x, unit if code != 'TL' else 'Türk Lirası', sub)
                st, mn, rd, rm = num(blk.get('statementDebt')), num(blk.get('minPayment')), num(blk.get('remainingDebt')), num(blk.get('remainingMinPayment'))
                p = pre() if first else ''
                first = False
                if code == 'TL':
                    if rm > 0 and rm >= mn:
                        s = 'Türk Lirası borcunuz %s, ödenmesi gereken minimum tutar %s\'dir.' % (f(st), f(mn))
                    elif rm <= 0:
                        s = 'Türk Lirası borcunuz %s, kalan toplam borcunuz %s\'dir. Minimum ödemenizi yaptığınız için teşekkür ederiz.' % (f(st), f(rd))
                    else:
                        s = 'Türk Lirası borcunuz %s, ödenmesi gereken minimum tutar %s, kalan toplam borcunuz %s, kalan minimum ödeme tutarınız %s\'dir.' % (f(st), f(mn), f(rd), f(rm))
                else:
                    s = '%s borcunuz %s, kalan toplam borcunuz %s, ödenmesi gereken minimum tutar %s\'dir.' % (nmc, f(st), f(rd), f(mn))
                out.append((p + s) if p else s)
            if clear and debtors:
                if len(clear) == 1: cs = clear[0]
                else: cs = ', '.join(clear[:-1]) + ' ve ' + clear[-1]
                out.append('%s borcunuz bulunmamaktadır.' % cs)
            if str(b.get('automaticPaymentFlag')) == 'Y' and lpd and t > lpd:
                ra = num((blocks.get('TL') or {}).get('remainAutomaticPaymentAmount'))
                if ra > 0:
                    out.append('Otomatik ödeme talimatınızdan tahsil edilecek kalan tutar %s\'dır.' % tl(ra))
            if lpd and lpd == t:
                out.append('Borçlarınız için son ödeme tarihiniz bugündür.')
            elif lpd and t > lpd:
                out.append('Son ödeme tarihiniz olan %s geçmiştir.' % sdate(lp))
            else:
                out.append('Borçlarınız için son ödeme tarihiniz %s.' % sdate(lp))
        vars['reading_text'] = ' '.join(out)
        vars['cur_last4'] = str(b.get('cardNumberLast4'))
        vars['cur_last4_spoken'] = last4
        vars['cur_name'] = nm
        vars['cur_statement_date'] = str(sd or '')
        rdn = int(num(vars.get('reads_done'))) + 1
        vars['reads_done'] = str(rdn)
        multi = vars.get('card_state') == 'multi'
        he = vars.get('has_email') == 'yes'
        offer = 'Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim.' if he else 'Hesap kesim tarihinizi değiştirebilirim.'
        vars['offer_text'] = offer
        vars['next_question'] = 'Başka bir kartınızın borcunu öğrenmek ister misiniz?' if multi else offer
    vars['get_balance_status'] = 'used'
except Exception as e:
    vars['reading_state'] = 'error'
    vars['reading_text'] = ''
'''

WEEK_PREP = HELPERS + r'''
try:
    vars['week_state'] = 'error'
    w = load('week_data', 'statement_week_get_response.data.data.')
    if isinstance(w, dict) and w.get('statementWeek') not in (None, ''):
        cw = int(num(w.get('statementWeek')))
        vars['cur_week'] = str(cw)
        vars['cur_day'] = str(int(num(w.get('statementDay'))))
        opts = [str(i) for i in (1, 2, 3, 4) if i != cw]
        vars['week_options'] = ', '.join(o + '.' for o in opts[:-1]) + ' ya da ' + opts[-1] + '.'
        nm = w.get('productName') or vars.get('cur_name') or ''
        s = '%s kartınızın hesap kesim tarihi her ayın %d. haftası olarak tanımlı. Bir sonraki hesap kesim tarihiniz %s, son ödeme tarihiniz %s.' % (nm, cw, sdate(w.get('nextStatementDate')), sdate(w.get('nextLastPayDate')))
        rel = str(w.get('relationType') or '')
        vars['joint_note'] = ''
        if rel in ('M', 'C'):
            s += ' Bu kartınız, sonu %s ile biten %s kartınızla ortak ekstreye sahiptir; ikisinin hesap kesim tarihi aynıdır.' % (digits(str(w.get('relatedCardNumber') or '')[-4:]), w.get('relatedCardProductName') or '')
            if rel == 'M':
                vars['joint_note'] = 'Bu değişiklik kartınıza bağlı %s kartınızı da etkileyecek. ' % (w.get('relatedCardProductName') or '')
            else:
                vars['joint_note'] = 'Bu değişiklik kartınızın bağlı olduğu %s kartınızı da etkileyecek. ' % (w.get('relatedCardProductName') or '')
        vars['week_intro'] = s
        vars['week_state'] = 'ok'
        vars['chosen_week'] = ''
        vars['week_msg'] = ''
except Exception:
    vars['week_state'] = 'error'
'''

WEEK_CHECK = HELPERS + r'''
try:
    cwk = str(vars.get('chosen_week') or '').strip()
    cw = str(vars.get('cur_week') or '')
    vars['week_verdict'] = 'retry'
    if cwk in ('1', '2', '3', '4') and cwk != cw:
        vars['week_verdict'] = 'ok'
        vars['new_week'] = cwk
    elif cwk == cw:
        vars['week_msg'] = 'Kartınızın hesap kesim haftası zaten ayın %s. haftası, bunun için bir değişiklik gerekmiyor.' % cw
        vars['chosen_week'] = ''
    else:
        vars['week_msg'] = 'Yalnızca okuduğum haftalardan birini seçebilirsiniz.'
        vars['chosen_week'] = ''
except Exception:
    vars['week_verdict'] = 'retry'
'''

DECIDE_PREP = HELPERS + r'''
try:
    vars['decide_state'] = 'error'
    d = load('decide_data', 'statement_week_decide_response.data.data.')
    if isinstance(d, dict) and d.get('statementDate'):
        vars['new_sd'] = sdate(d.get('statementDate'))
