def api_fn(name, path, body_props, required=None, desc="", timeout=15000):
    return {
        "type": "function",
        "config": {"timeoutMs": timeout, "maxRetries": 0},
        "function": {
            "name": name, "handler": "__function__:api_call", "description": desc or name,
            "parameters": {"type": "object", "properties": {
                "url": {"type": "string", "default": BASE + path},
                "method": {"type": "string", "default": "POST"},
                "headers": HDR,
                "body": {"type": "object", "properties": {
                    "data": {"type": "object", "properties": body_props, "required": required or list(body_props)},
                    "call": {"type": "object", "properties": {"ani": {"type": "string", "default": ""}, "lang": {"type": "string", "default": "tr"}}}
                }, "required": ["data"]}}}},
        "post_process_code": POST_HOOK,
    }


def api_node(name, fn, mapping, nxt):
    return {"name": name, "node_type": "api_request", "passthrough": True,
            "passthrough_default_transition": nxt, "on_enter": {"type": "silent"},
            "pre_actions": [fn], "response_mapping": mapping,
            "transitions": [{"target_node": nxt, "description": "always", "condition": {"operator": "always"}}]}


def code_node(name, code, transitions, default):
    code = code.replace("{{", "{ {").replace("}}", "} }")
    return {"name": name, "node_type": "code", "passthrough": True,
            "passthrough_default_transition": default, "on_enter": {"type": "silent"},
            "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec",
                             "parameters": {"type": "object", "properties": {
                                 "code": {"type": "string", "default": code},
                                 "timeout_ms": {"type": "number", "default": 15000}}}}}],
            "transitions": transitions + [{"target_node": default, "description": "always", "condition": {"operator": "always"}}]}


def eq(var, val, target, desc):
    return {"target_node": target, "description": desc,
            "condition": {"logic": "or", "conditions": [{"variable": var, "operator": "equals", "operand": val}]}}


def intent(target, desc):
    return {"target_node": target, "description": desc, "condition": {"operator": "matches_intent", "description": desc}}


def end_node(name, msg):
    return {"name": name, "node_type": "end_call", "on_enter": {"type": "silent"},
            "terminal": {"type": "function", "function": {"name": name, "handler": "__function__:end_call",
                         "parameters": {"type": "object", "properties": {
                             "message_mode": {"type": "string", "default": "custom"},
                             "spoken_message": {"type": "string", "default": msg}}}}},
            "transitions": []}


HELPERS = r'''
import json, re, datetime
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
AY = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
def w3(n):
    h, r = divmod(n, 100); t, o = divmod(r, 10)
    s = []
    if h: s.append(('' if h == 1 else ONES[h] + ' ') + 'yüz')
    if t: s.append(TENS[t])
    if o: s.append(ONES[o])
    return ' '.join(s)
def words(n):
    n = int(n)
    if n == 0: return 'sıfır'
    parts = []
    for val, nm in ((10**9, 'milyar'), (10**6, 'milyon'), (1000, 'bin')):
        q, n = divmod(n, val)
        if q:
            parts.append('bin' if (val == 1000 and q == 1) else w3(q) + ' ' + nm)
    if n: parts.append(w3(n))
    return ' '.join(parts)
def money(x, unit, sub):
    x = round(abs(float(x)) + 1e-9, 2)
    a = int(x); c = int(round((x - a) * 100))
    s = words(a) + ' ' + unit
    if c: s += ' ' + words(c) + ' ' + sub
    return s
def tl(x): return money(x, 'Türk Lirası', 'kuruş')
def pdate(s):
    try:
        d, m, y = str(s).strip().split('.')
        return datetime.date(int(y), int(m), int(d))
    except Exception:
        return None
def sdate(s):
    d = pdate(s)
    return ('%d %s %d' % (d.day, AY[d.month], d.year)) if d else str(s)
def digits(s): return ' '.join(DIG[int(c)] for c in str(s) if c.isdigit())
def today():
    try: return datetime.date.fromisoformat(str(vars.get('now') or '')[:10])
    except Exception: return datetime.date.today()
def load(name, prefix):
    v = vars.get(name)
    if isinstance(v, str):
        try: v = json.loads(v)
        except Exception: v = None
    if isinstance(v, (dict, list)) and v: return v
    flat = {}
    for k in list(vars.keys()):
        if k.startswith(prefix):
            flat[k[len(prefix):]] = vars.get(k)
    if not flat: return None
    root = {}
    for k, val in flat.items():
        cur = root; ps = k.split('.')
        for p in ps[:-1]: cur = cur.setdefault(p, {})
        cur[ps[-1]] = val
    def fix(o):
        if isinstance(o, dict):
            if o and all(str(k).isdigit() for k in o):
                return [fix(o[k]) for k in sorted(o, key=lambda z: int(z))]
            return {k: fix(v2) for k, v2 in o.items()}
        return o
    return fix(root)
def num(x):
    try: return float(x)
    except Exception: return 0.0
'''

